import sys

def NBitBinary(n):
    result = []

    def backtrack(current, ones, zeros):
        if len(current) == n:
            result.append(current)
            return

        # Try adding '1'
        backtrack(current + '1', ones + 1, zeros)

        # Try adding '0' only if ones > zeros (to maintain prefix condition)
        if ones > zeros:
            backtrack(current + '0', ones, zeros + 1)

    backtrack("", 0, 0)
    return result

if __name__ == "__main__":
    try:
        line = sys.stdin.read().strip()
        if line:
            n = int(line)
            output_list = NBitBinary(n)
            print(" ".join(output_list))
    except ValueError:
        pass
